        /*
        |--------------------------------------------------------------------------
        | Mapping Account berdasarkan NIP
        |--------------------------------------------------------------------------
        |
        | Ini yang sebelumnya belum ada sehingga muncul:
        |
        | Undefined variable '$userMap'
        |
        */

        $jabatanMap = [];

        foreach ($jabatans as $jabatan) {
            $jabatanMap[(int) $jabatan['id']] = $jabatan['nama_jabatan'];
        }

        $userMap = [];

        foreach ($users as $user) {
            $userMap[$user['nip']] = $user;
        }

        /*
        |--------------------------------------------------------------------------
        | Gabungkan Outsourcing + Account
        |--------------------------------------------------------------------------
        |
        | Satu NIP = satu record pada tabel users.
        |
        */

        foreach ($outsourcings as $outsourcing) {
            $nip = $outsourcing['nip'];

            $account = $userMap[$nip] ?? null;

            $jabatanId = (int) $outsourcing['jabatan_id'];

            User::updateOrCreate(
                [
                    'nip' => $nip,
                ],
                [
                    'uuid' => $outsourcing['uuid'],
                    'name' => $outsourcing['name'],
                    'image' => $outsourcing['image'],
                    'jabatan' => $jabatanMap[$jabatanId] ?? null,
                    'kode_biro' => $outsourcing['kode_biro'],
                    'is_active' => (bool) $outsourcing['is_active'],
                    'email' => $account['email'] ?? null,
                    'role' => $account['role'] ?? [],
                    'password' => $account['password'] ?? null,
                ]
            );
        }

